2	 * Converts SCREAMING_SNAKE_CASE to "Pretty Case"
3	 * @param value - The string to convert
4	 * @returns Formatted string with proper capitalization
5	 */
6	export const toPrettyCase = (value: string): string => {
7	  return value
8	    .split('_')
9	    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
10	    .join(' ');
11	};
