13	/**
14	 * Generates a pretty project name from a file path
15	 * Converts directory names like "my-awesome-project" to "My Awesome Project"
16	 * @param path - The file path to extract name from
17	 * @returns Formatted project name
18	 */
19	export const generateProjectNameFromPath = (path: string): string => {
20	  const dirName = path.split('/').filter(Boolean).pop() || '';
21	  return dirName.replace(/[-_]/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase());
22	};
