1	/** Downloads an attachment from a URL and triggers a browser save dialog. */
2	export async function downloadBlobUrl(
3	  url: string,
4	  filename: string
5	): Promise<void> {
6	  const response = await fetch(url, {
7	    method: 'GET',
8	    mode: 'cors',
9	    credentials: 'omit',
10	  });
11	
12	  if (!response.ok) {
13	    throw new Error('Failed to download attachment');
14	  }
15	
16	  const blob = await response.blob();
17	  const objectUrl = URL.createObjectURL(blob);
18	
19	  try {
20	    const anchor = document.createElement('a');
21	    anchor.href = objectUrl;
22	    anchor.download = filename;
23	    document.body.appendChild(anchor);
24	    anchor.click();
25	    document.body.removeChild(anchor);
26	  } finally {
27	    URL.revokeObjectURL(objectUrl);
28	  }
29	}
