93	/** Extracts attachment IDs from `attachment://` references in markdown content. */
94	export function extractAttachmentIds(content: string): Set<string> {
95	  const ids = new Set<string>();
96	  const regex = /attachment:\/\/([a-f0-9-]+)/g;
97	  let match;
98	  while ((match = regex.exec(content)) !== null) {
99	    ids.add(match[1]);
100	  }
101	  return ids;
102	}
