59	export class ClickToComponentListener {
60	  private handlers: EventHandlers = {};
61	  private messageListener: ((event: MessageEvent) => void) | null = null;
62	
63	  constructor(handlers: EventHandlers = {}) {
64	    this.handlers = handlers;
65	  }
66	
67	  /**
68	   * Start listening for messages from click-to-component iframe
69	   */
70	  start(): void {
71	    if (this.messageListener) {
72	      this.stop(); // Clean up existing listener
73	    }
74	
75	    this.messageListener = (event: MessageEvent) => {
76	      const data = event.data as ClickToComponentMessage;
77	
78	      // Only handle messages from our click-to-component tool
79	      if (!data || data.source !== 'click-to-component') {
80	        return;
81	      }
82	
83	      switch (data.type) {
84	        case 'ready':
85	          if (event.source) {
86	            const enableMsg: ClickToComponentEnableMessage = {
87	              source: 'click-to-component',
88	              version: 1,
89	              type: 'enable-button',
90	            };
91	            (event.source as Window).postMessage(enableMsg, '*');
92	          }
93	          this.handlers.onReady?.();
94	          break;
95	
96	        case 'open-in-editor':
97	          if (data.payload) {
98	            this.handlers.onOpenInEditor?.(data.payload);
99	          }
100	          break;
101	
102	        default:
103	          this.handlers.onUnknownMessage?.(data);
104	      }
105	    };
106	
107	    window.addEventListener('message', this.messageListener);
108	  }
109	
110	  /**
111	   * Stop listening for messages
112	   */
113	  stop(): void {
114	    if (this.messageListener) {
115	      window.removeEventListener('message', this.messageListener);
116	      this.messageListener = null;
117	    }
118	  }
119	
120	  /**
121	   * Update event handlers
122	   */
123	  setHandlers(handlers: EventHandlers): void {
124	    this.handlers = { ...this.handlers, ...handlers };
125	  }
126	
127	  /**
128	   * Send a message to the iframe (if needed)
129	   */
130	  sendToIframe(iframe: HTMLIFrameElement, message: unknown): void {
131	    if (iframe.contentWindow) {
132	      iframe.contentWindow.postMessage(message, '*');
133	    }
134	  }
135	}
